    @field_validator(
        "by_role_absolute", "by_role_percent", "by_region_absolute",
        "growth_percent", "growth_absolute", mode="before"
    )
    @classmethod
    def _coerce_dicts(cls, v: Any) -> Any:
        return _empty_dict_if_none(v)


class CompanyFunding(BaseModel):
